"use client";

import { LayoutGroup, motion } from "motion/react";

import { cn } from "@/lib/utils";

export default function StackedItems() {
  const stack: string[] = [
    "React",
    "Next.js",
    "TypeScript",
    "Tailwind CSS",
    "Node.js",
    "Redis",
  ];

  return (
    <div className="my-4 flex h-full w-full flex-wrap gap-1">
      <LayoutGroup>
        {stack.map((item, idx) => (
          <StackItem
            key={item + idx}
            technology={item}
            className="-mr-3 hover:z-10"
          />
        ))}
      </LayoutGroup>
    </div>
  );
}

const StackItem = ({
  technology,
  className,
}: {
  technology: string;
  className?: string;
}) => {
  const getLogoForTechnology = (technology: string) => {
    const logoMap: Record<string, React.ReactNode> = {
      React: <ReactLogo className="size-6 shrink-0 dark:text-neutral-200" />,
      "Tailwind CSS": (
        <TailwindLogo className="size-6 shrink-0 dark:text-neutral-200" />
      ),
      "Next.js": <NextLogo className="size-6 shrink-0 dark:text-neutral-200" />,
      TypeScript: (
        <TypeScriptLogo className="size-6 shrink-0 dark:text-neutral-200" />
      ),
      "Node.js": <NodeLogo className="size-6 shrink-0 dark:text-neutral-200" />,
      Redis: <RedisLogo className="size-6 shrink-0 dark:text-neutral-200" />,
    };

    return logoMap[technology];
  };

  return (
    <motion.div
      layout
      whileHover="animate"
      whileTap="animate"
      initial="initial"
      className={cn(
        "flex items-center justify-start rounded-full border border-neutral-200 bg-neutral-100 p-1 text-base text-neutral-500 dark:border-neutral-700 dark:bg-neutral-800",
        className
      )}
    >
      <motion.span
        variants={{
          animate: { paddingRight: 2 },
        }}
        transition={{
          type: "spring",
        }}
      >
        {getLogoForTechnology(technology)}
      </motion.span>
      <motion.span
        variants={{
          initial: { width: 0 },
          animate: { width: "auto" },
          exit: { width: 0 },
        }}
        transition={{
          type: "spring",
          stiffness: 200,
          damping: 25,
          mass: 0.5,
        }}
        className="overflow-hidden whitespace-nowrap text-neutral-500 dark:text-neutral-200"
      >
        {technology}
      </motion.span>
    </motion.div>
  );
};

